  --cream-dark:   #F2EDE3;
  --cream-mid:    #EDE5D8;
  --brown-dark:   #3D2314;
  --brown-mid:    #6B3D22;
  --brown:        #8B5E3C;
  --brown-light:  #B88B6A;
  --brown-muted:  #C4A882;
  --text-primary: #2C1810;
  --text-body:    #4A3728;
  --text-muted:   #7A6055;
  --white:        #FFFFFF;

  --font-bengali: 'Hind Siliguri', 'Tiro Bangla', sans-serif;
  --font-serif:   'Tiro Bangla', 'Hind Siliguri', serif;

  --space-xs:  0.5rem;
  --space-sm:  1rem;
  --space-md:  1.5rem;
  --space-lg:  2.5rem;
  --space-xl:  4rem;
  --space-2xl: 6rem;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --transition: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  --shadow-sm: 0 2px 8px rgba(60, 35, 20, 0.08);
  --shadow-md: 0 6px 24px rgba(60, 35, 20, 0.12);
  --shadow-lg: 0 16px 48px rgba(60, 35, 20, 0.18);

  --max-width: 1100px;
  --nav-h: 72px;
}

